import csv, numpy as np, sys
rows = list(csv.DictReader(open("../../responses.csv")))
p = np.load("scratch/inc_p.npy")
for s in sys.argv[1:]:
    cells={}
    for i,r in enumerate(rows):
        if r["number_set"]==s:
            c=cells.setdefault(int(r["target"]),[0,0,p[i]]); c[0]+=1; c[1]+=int(r["rating"])
    print(s, " ".join(f"{t}:{c[1]}/{c[0]}({c[2]:.2f})" for t,c in sorted(cells.items())))
EOF
